// File: app/api/health/route.ts
// Checks whether Vercel can see your environment variables.
// DELETE this file once you're done debugging.

import { NextResponse } from "next/server";

export const dynamic = "force-dynamic";

// ─── CHANGE THIS LIST TO YOUR VARIABLES ───
const REQUIRED = [
  "NEXT_PUBLIC_SUPABASE_URL",
  "NEXT_PUBLIC_SUPABASE_ANON_KEY",
  "SUPABASE_SERVICE_ROLE_KEY",
  "OPENAI_API_KEY",
];

export async function GET() {
  const review = REQUIRED.map((name) => {
    const value = process.env[name];
    const clean = value ? value.trim() : "";
    return {
      name,
      present: clean.length > 0,
      length: clean.length,
      startsWith: clean ? clean.slice(0, 4) + "..." : null,
      // Typical warning: you pasted the key with quotes or a stray space
      suspicious: Boolean(value && value !== clean) || clean.startsWith("\""),
    };
  });

  const missing = review.filter((v) => !v.present).map((v) => v.name);

  return NextResponse.json({
    environment: process.env.VERCEL_ENV || "development (your computer)",
    branch: process.env.VERCEL_GIT_COMMIT_REF || "no branch",
    allGood: missing.length === 0,
    missing,
    review,
  });
}
